<?php
declare(strict_types=1);namespace App\Controllers\Fiscal;
use App\Controllers\Security_Controller;use App\Services\Fiscal\Pdf\FiscalPdfTemplateResolver;use Throwable;
final class PdfTemplates extends Security_Controller{
 public function index(){$this->guard('fiscal_pdf_templates_view');$db=db_connect();return$this->template->rander('fiscal/pdf_templates/index',['issuers'=>$db->table('fiscal_profiles')->select('id,legal_name,rfc')->where(['profile_type'=>'issuer','status'=>'ready'])->orderBy('legal_name')->get()->getResult(),'templates'=>$db->table('fiscal_issuer_pdf_templates')->orderBy('issuer_id')->orderBy('document_type')->get()->getResult(),'can_manage'=>$this->allowed('fiscal_pdf_templates_manage')]);}
 public function save():void{$this->guard('fiscal_pdf_templates_manage');try{$issuer=(int)$this->request->getPost('issuer_id');$provider=strtolower(trim((string)$this->request->getPost('provider')));$type=strtoupper(trim((string)$this->request->getPost('document_type')));$code=trim((string)$this->request->getPost('template_code'));$active=$this->request->getPost('is_active')?1:0;if(!$issuer||!in_array($provider,['fake','timbradorxpress-tools'],true)||!in_array($type,['I','E','P','T','N'],true)||!(new FiscalPdfTemplateResolver())->valid($code))throw new \RuntimeException('Datos de plantilla inválidos.');$db=db_connect();$old=$db->table('fiscal_issuer_pdf_templates')->where(['issuer_id'=>$issuer,'provider'=>$provider,'document_type'=>$type])->get(1)->getRow();$now=get_current_utc_time();$data=['issuer_id'=>$issuer,'provider'=>$provider,'document_type'=>$type,'template_code'=>$code,'is_active'=>$active,'updated_by'=>$this->login_user->id,'updated_at'=>$now];if($old){$db->table('fiscal_issuer_pdf_templates')->where('id',$old->id)->update($data);$id=(int)$old->id;$action=$active?($old->template_code===$code?'pdf_template_configured':'pdf_template_updated'):'pdf_template_disabled';}else{$data+=['created_by'=>$this->login_user->id,'created_at'=>$now];$db->table('fiscal_issuer_pdf_templates')->insert($data);$id=(int)$db->insertID();$action=$active?'pdf_template_configured':'pdf_template_disabled';}$db->table('fiscal_pdf_template_audit')->insert(['template_id'=>$id,'issuer_id'=>$issuer,'action'=>$action,'old_template_code'=>$old?->template_code,'new_template_code'=>$code,'user_id'=>$this->login_user->id,'created_at'=>$now]);echo json_encode(['success'=>true,'message'=>app_lang('pdf_template_saved'),'csrf'=>['name'=>csrf_token(),'hash'=>csrf_hash()]]);}catch(Throwable$e){log_message('warning','Fiscal PDF template save rejected: {type}',['type'=>get_class($e)]);echo json_encode(['success'=>false,'message'=>app_lang('pdf_template_invalid'),'csrf'=>['name'=>csrf_token(),'hash'=>csrf_hash()]]);}}
 private function allowed(string$p):bool{if($this->login_user->is_admin)return true;$all=is_array($this->login_user->permissions)?$this->login_user->permissions:(@unserialize((string)$this->login_user->permissions)?:[]);return(bool)get_array_value($all,$p);}private function guard(string$p):void{if(!$this->allowed($p))app_redirect('forbidden');}
}
